     * and are skipped on the other. Raise `$min` only once no open run is on an older path. Enforced by the engine.
     */
    public function change(string $id, int $min = 0, int $max = 1): self
    {
        if ($min > $max) {
            throw new \InvalidArgumentException("change \"{$id}\" in workflow \"{$this->name}\": min is above max");
        }
        $this->changes[$id] = ['min' => $min, 'max' => $max];
        return $this;
    }

    /**
     * An update handler (`JoobQClient::updateWorkflow`, Pro): `$validate` (a reference, e.g. `DSL::updateInput('name')`)
     * must be truthy or the update is rejected with `$message`; then `$handler` runs as an activity of the run
     * (`<workflow>/@update/<name>`, not retried, `$timeoutMs` default 30 s; its payload is `$input`, by default the
     * update's input, already resolved by the engine, and its return value is the result), or, without one, `$result`
     * is the result. `$input` and `$result` hold references only (`DSL::updateInput()`, `input()`, `output()`, `ref()`,
     * in arrays; a literal is refused when the blueprint is built). Enforced by the engine.
     */
    public function update(
        string $name,
        ?callable $handler = null,
        ?DataRef $validate = null,
        ?string $message = null,
        mixed $input = null,
        mixed $result = null,
        ?int $timeoutMs = null
    ): self {
        if (isset($this->updates[$name])) {
            throw new \InvalidArgumentException("Duplicate update \"{$name}\" in workflow \"{$this->name}\"");
        }
        if ($input !== null) {
            DSL::template($input, "update {$name}.input");
        }
        if ($result !== null) {
            DSL::template($result, "update {$name}.result");
        }
        $this->updates[$name] = new UpdateDef($name, $handler, $validate, $message, $input, $result, $timeoutMs);
        return $this;
    }

    /**
     * A cancellation scope: the nodes built on the given blueprint run in order and can be cancelled as a unit (from the
     * console or API, or after `$timeoutMs` from its first step's start) while the rest of the run goes on; a cancelled
     * step counts as finished with a null output, and a running one sees the cancel as `$ctx->heartbeat()` answering
     * true. A `$nonCancellable` scope holds cleanup that still runs when the workflow is cancelled, times out or fails (it
     * cannot have a timeout). Scopes do not nest.
     */
    public function scope(string $name, callable $build, ?int $timeoutMs = null, bool $nonCancellable = false): self
    {
        if ($this->inScope) {
            throw new \InvalidArgumentException("scope \"{$name}\" in workflow \"{$this->name}\" is inside another scope: scopes do not nest");
        }
        if ($nonCancellable && $timeoutMs !== null) {
            throw new \InvalidArgumentException("scope \"{$name}\" is non_cancellable and cannot time out");
        }
        $sub = $this->subBlueprint(true);
        $build($sub);
        if ($sub->steps === []) {
            throw new \InvalidArgumentException("scope \"{$name}\" in workflow \"{$this->name}\" has no steps");
        }
        $this->steps[] = ['kind' => 'scope', 'name' => $name, 'children' => $sub->steps, 'timeout_ms' => $timeoutMs, 'non_cancellable' => $nonCancellable];
        return $this;
    }

    /** The workflow's structure as data, as the worker registers it with the gateway (`CONTRACT.md`). */
    public function toBlueprint(): array
    {
        $queries = [];
        foreach ($this->queries as $name => $ref) {
            $queries[$name] = $ref->expr;
        }
        $blueprint = [
            'name' => $this->name,
            'version' => $this->version,
            'task_queue' => $this->taskQueue,
            'queries' => (object)$queries,
            'nodes' => array_map([self::class, 'blueprintNode'], $this->steps),
        ];
        if ($this->timeoutMs !== null) {
            $blueprint['timeout_ms'] = $this->timeoutMs; // the whole run's deadline, enforced by the engine
        }
        if ($this->continuation !== null) {
            $blueprint['continue_as_new'] = (object)$this->continuation;
        }
        if ($this->changes !== []) {
            $blueprint['changes'] = [];
            foreach ($this->changes as $id => $bounds) {
                $blueprint['changes'][] = ['id' => $id] + $bounds;
            }
        }
        if ($this->updates !== []) {
            $blueprint['updates'] = (object)array_map(fn (UpdateDef $u) => $u->toSpec(), $this->updates);
        }
        return $blueprint;
    }

    private static function blueprintNode(array $node): array
    {
        $out = ['name' => $node['name'], 'kind' => $node['kind']];
        switch ($node['kind']) {
            case 'parallel':
            case 'sequence':
                $out['children'] = array_map([self::class, 'blueprintNode'], $node['children']);
                break;
            case 'scope':
                $out['children'] = array_map([self::class, 'blueprintNode'], $node['children']);
                if ($node['timeout_ms'] !== null) {
                    $out['timeout_ms'] = $node['timeout_ms'];
                }
                if ($node['non_cancellable']) {
                    $out['non_cancellable'] = true;
                }
                break;
            case 'wait_for':
                $out['signal'] = $node['signal'];
                $out['timeout_ms'] = $node['timeout_ms'];
                break;
            case 'timer':
                $out['for_ms'] = $node['duration_ms'];
                break;
            case 'child':
                $out['workflow'] = $node['workflow'];
                if ($node['input'] !== null) {
                    $out['input'] = DSL::template($node['input'], "{$node['name']}.input");
                }
                break;
            default:
                $out['activity'] = DSL::callableName($node['handler']);
                $out['references'] = $node['input'] === null ? ['${input}'] : DSL::references($node['input']);
                foreach (['step_timeout_ms' => 'timeout_ms', 'heartbeat_ms' => 'heartbeat_ms', 'schedule_to_start_ms' => 'schedule_to_start_ms'] as $key => $field) {
                    if (($node[$key] ?? null) !== null) {
                        $out[$field] = $node[$key];
                    }
                }
                if ($node['retry'] instanceof RetryPolicy) {
                    $out['retry'] = self::retryOf($node['retry']);
                }
        }
        // A step, wait, timer or child can be undone and made conditional.
        if (($node['compensate'] ?? null) instanceof Compensation) {
            $c = $node['compensate'];
            $out['compensate'] = [
                'activity' => DSL::callableName($c->handler),
                'references' => DSL::references($c->input ?? DSL::output($node['name'])),
            ];
        }
        if (($node['only_if'] ?? null) instanceof DataRef) {
            $out['only_if'] = $node['only_if']->expr;
        }
        if (($node['gate'] ?? null) instanceof Gate) {
            $out['gate'] = $node['gate']->toArray();
        }
        if (!empty($node['after'])) {
            $out['after'] = $node['after'];
        }
        return $out;
    }

    private static function retryOf(RetryPolicy $r): array
    {
        $out = ['attempts' => $r->attempts, 'initial_ms' => $r->initialMs, 'backoff' => $r->backoff, 'maximum_ms' => $r->maximumMs];
        if ($r->nonRetryable !== []) {
            $out['non_retryable'] = $r->nonRetryable;
        }
        return $out;
    }

    /** Starts the branches built on the given blueprint together; what follows waits for every branch. */
    public function parallel(callable $build): self
    {
        return $this->group('parallel', $build);
    }

    /** Runs the nodes built on the given blueprint in order. */
    public function sequence(callable $build): self
    {
        return $this->group('sequence', $build);
    }

    /** The leaf nodes (steps, waits, timers, children) of the given nodes, in order, walking into `sequence`, `parallel` and `scope`. */
    private static function leafNodesOf(array $nodes): array
    {
        $found = [];
        foreach ($nodes as $node) {
            if (isset($node['children'])) {
                array_push($found, ...self::leafNodesOf($node['children']));
            } else {
                $found[] = $node;
            }
        }
        return $found;
    }

    /**
     * The handlers of this workflow's steps, by the activity name the engine sends them under (`<workflow>/<step>`,
     * compensations `<workflow>/<node>/compensate`, for steps, waits, timers and children; a child itself has no handler,
     * the engine runs the child workflow; update handlers `<workflow>/@update/<name>`). Each runs its step once: the
     * engine conducts the run (it retries, compensates and waits). A step's input is resolved against the run's input
     * (the task's payload) and the outputs of the steps that completed (the task's checkpoints); an update handler gets
     * its payload as is (the engine resolved it).
     * @return array<string, \Closure(mixed, ExecutionContext): mixed>
     */
    public function activities(): array
    {
        $found = [];
        foreach (self::leafNodesOf($this->steps) as $node) {
            if ($node['kind'] === 'step') {
                $handler = $node['handler'];
                $spec = $node['input'];
                $found[self::activityName($this->name, $node['name'])] = static fn (mixed $workflowInput, ExecutionContext $ctx): mixed
                    => $handler(DSL::resolveReferences($spec, $workflowInput, (array)($ctx->task['checkpoints'] ?? [])), $ctx);
            }
            $comp = $node['compensate'] ?? null;
            if ($comp instanceof Compensation) {
                $compSpec = $comp->input ?? DSL::output($node['name']);
                $found[self::activityName($this->name, $node['name'], true)] = static fn (mixed $workflowInput, ExecutionContext $ctx): mixed
                    => ($comp->handler)(DSL::resolveReferences($compSpec, $workflowInput, (array)($ctx->task['checkpoints'] ?? [])), $ctx);
            }
        }
        foreach ($this->updates as $update) {
            if ($update->handler !== null) {
                $updateHandler = $update->handler;
                // The engine already resolved the handler's input: the task's payload is passed on as is.
                $found[self::updateActivityName($this->name, $update->name)] = static fn (mixed $payload, ExecutionContext $ctx): mixed
                    => $updateHandler($payload, $ctx);
            }
        }
        return $found;
    }

    /** The activity the engine sends an update handler of an SDK workflow under. */
    public static function updateActivityName(string $workflowName, string $update): string
    {
        return "{$workflowName}/@update/{$update}";
    }

    /** The activity the engine sends a step (or its compensation) of an SDK workflow under. */
    public static function activityName(string $workflowName, string $step, bool $compensate = false): string
    {
        return $compensate ? "{$workflowName}/{$step}/compensate" : "{$workflowName}/{$step}";
    }

    /** A blueprint to build a group's nodes on; it knows whether it is inside a scope. */
    private function subBlueprint(bool $inScope): self
    {
        $sub = new WorkflowBlueprint($this->name, $this->version, $this->timeoutMs, $this->taskQueue);
        $sub->inScope = $inScope;
        return $sub;
    }

    private function group(string $kind, callable $build): self
    {
        $sub = $this->subBlueprint($this->inScope);
        $build($sub);
        $this->steps[] = ['kind' => $kind, 'name' => $kind . '_' . (count($this->steps) + 1), 'children' => $sub->steps];
        return $this;
    }
}

final class ExecutionContext
{
    public array $context;

    /** When the last engine heartbeat (`heartbeat_ms` tasks) was sent, in monotonic ms, and whether it said cancel. */
    private float $lastBeatMs = -INF;
    private bool $beatCancel = false;

    /**
     * @param array $task the leased task as the gateway sent it (`lease_token`, `name`, `payload`, `attempt`, `checkpoints`,
     *   `context`, ...; `heartbeat_ms` is an engine step's heartbeat timeout, null for most tasks: call `heartbeat()`
     *   more often than this)
     */
    public function __construct(
        public readonly array $task,
        public readonly string $workerId,
        public readonly JoobQClient $client,
        public readonly int $leaseTtlMs = 30000
    ) {
        $this->context = (array)($task['context'] ?? []);
    }

    /**
     * Renews this task's lease (`POST /sdk/tasks/:token/heartbeat`) and answers whether the run was cancelled. For a step
     * with `heartbeat_ms` this call is also what tells the engine the step is alive (the worker's own renewals do not, so
     * a handler that stops calling it is timed out); it is then sent at most every third of `heartbeat_ms` (in between it
     * answers what the last one said), and a failed call is ignored: the next one tries again.
     */
    public function heartbeat(?int $leaseTtlMs = null): bool
    {
        $beatMs = (int)($this->task['heartbeat_ms'] ?? 0);
        if ($beatMs > 0) {
            $now = hrtime(true) / 1e6;
            if ($now - $this->lastBeatMs >= max(100, intdiv($beatMs, 3))) {
                $this->lastBeatMs = $now;
                try {
                    $res = $this->client->heartbeatTask((string)$this->task['lease_token'], $this->workerId, $leaseTtlMs ?? $this->leaseTtlMs);
                    $this->beatCancel = (bool)($res['cancel_requested'] ?? false);
                } catch (\Throwable) {
                    // the next window's beat tries again; the engine's deadline decides
                }
            }
            return $this->beatCancel;
        }
        $res = $this->client->heartbeatTask((string)$this->task['lease_token'], $this->workerId, $leaseTtlMs ?? $this->leaseTtlMs);
        return (bool)($res['cancel_requested'] ?? false);
    }

    public function enqueueJob(string $queue, string $jobType, array $payload = [], array $options = []): array
    {
        $options['context'] = array_merge($this->context, (array)($options['context'] ?? []));
        return $this->client->enqueueJob($queue, $jobType, $payload, $options);
    }

    /** @param class-string<Job> $jobClass  Enqueues a defined job, carrying this handler's request context on. */
    public function enqueue(string $jobClass, array $payload = [], array $options = []): array
    {
        $options['context'] = array_merge($this->context, (array)($options['context'] ?? []));
        return $this->client->enqueue($jobClass, $payload, $options);
    }

    public function startWorkflow(string $name, mixed $input = null, array $options = []): array
    {
        $options['context'] = array_merge($this->context, (array)($options['context'] ?? []));
        return $this->client->startWorkflow($name, $input, $options);
    }

    /** See `JoobQClient::rateLimit`. */
    public function rateLimit(string $key, int $limit, int $periodMs): array
    {
        return $this->client->rateLimit($key, $limit, $periodMs);
    }

    /** See `JoobQClient::createBatch` (Pro); the members and callbacks carry this handler's request context. */
    public function createBatch(array $jobs, array $options = []): array
    {
        $options['context'] = array_merge($this->context, (array)($options['context'] ?? []));
        return $this->client->createBatch($jobs, $options);
    }

    /** See `JoobQClient::getBatch` (Pro). */
    public function getBatch(string $batchId): array
    {
        return $this->client->getBatch($batchId);
    }

    /** See `JoobQClient::signalWorkflow`. */
    public function signalWorkflow(string $id, string $name, mixed $payload = null): array
    {
        return $this->client->signalWorkflow($id, $name, $payload);
    }

    /** See `JoobQClient::updateWorkflow` (Pro). */
    public function updateWorkflow(string $id, string $name, mixed $input = null, ?string $updateId = null, ?int $waitMs = null): array
    {
        return $this->client->updateWorkflow($id, $name, $input, $updateId, $waitMs);
    }

    /** See `JoobQClient::describeWorkflow` (Pro). */
    public function describeWorkflow(string $id): array
    {
        return $this->client->describeWorkflow($id);
    }

    /** See `JoobQClient::workflowResult` (Pro). */
    public function workflowResult(string $id, int $waitMs = 0): array
    {
        return $this->client->workflowResult($id, $waitMs);
    }

    /** See `JoobQClient::workflowHistory` (Pro). */
    public function workflowHistory(string $id, int $afterSeq = 0, int $limit = 200): array
    {
        return $this->client->workflowHistory($id, $afterSeq, $limit);
    }

    /** See `JoobQClient::queryWorkflow` (Pro). */
    public function queryWorkflow(string $id, string $name): mixed
    {
        return $this->client->queryWorkflow($id, $name);
    }

    /** See `JoobQClient::upsertWorkflowAttributes` (Pro). */
    public function upsertWorkflowAttributes(string $id, ?array $set = null, ?array $remove = null): array
    {
        return $this->client->upsertWorkflowAttributes($id, $set, $remove);
    }
}

final class JoobQClient
{
    public const SDK_VERSION = SDK_VERSION;

    private string $gatewayUrl;
    private string $token;
    /** @var (callable(): array)|null */
    private $contextProvider;

    /**
     * Seconds one gateway call may take. A worker lowers it (`JoobQWorker`): a call that hangs for longer than a lease
     * would let every lease the worker holds expire while its tasks still run.
     */
    public float $requestTimeout = 60.0;

    /** This process's kept-alive curl handle (a forked process makes its own: `$curlPid`). */
    private ?\CurlHandle $curl = null;
    private int $curlPid = 0;

    public function __construct(string $gatewayUrl, string $token, ?callable $contextProvider = null)
    {
        $this->gatewayUrl = rtrim($gatewayUrl, '/');
        $this->token = $token;
        $this->contextProvider = $contextProvider;
    }

    /**
     * Enqueues many jobs with `POST /sdk/jobs/batch` (500 per call). Each item is `[JobClass::class, $payload]`,
     * `[JobClass::class, $payload, $options]` or `['queue' => ..., 'job_type' => ..., 'payload' => ..., ...options]`.
     * Answers one `['jid', 'queue', 'status']` per job, in order. (PHP has no threads: there is no enqueueAsync.)
     */
    public function enqueueMany(array $jobs, array $context = []): array
    {
        $bodies = [];
        foreach ($jobs as $item) {
            $bodies[] = $this->itemBody($item, $context);
        }
        $out = [];
        foreach (array_chunk($bodies, 500) as $chunk) {
            $out = array_merge($out, $this->post('/api/v1/sdk/jobs/batch', ['jobs' => $chunk])['jobs'] ?? []);
        }
        return $out;
    }

    /** One job of `enqueueMany` or `createBatch`: `[JobClass::class, $payload, $options]` or `['queue' => ..., ...]`. */
    private function itemBody(array $item, array $context): array
    {
        if (isset($item['queue'])) {
            $item['context'] = array_merge($context, (array)($item['context'] ?? []));
            return $this->jobBody((string)$item['queue'], (string)$item['job_type'], (array)($item['payload'] ?? []), $item);
        }
        [$jobClass, $payload] = $item;
        $options = (array)($item[2] ?? []);
        $options['context'] = array_merge($context, (array)($options['context'] ?? []));
        return $this->jobBody($jobClass::$queue, $jobClass::jobName(), (array)$payload, $options + [
            'max_retries' => $jobClass::$retries,
            'encrypt_fields' => $jobClass::$encryptedFields,
            'unique_ttl_ms' => $jobClass::$uniqueTtlMs,
        ]);
    }

    /**
     * Creates a Pro batch with `POST /sdk/batches`: 1 to 1000 member jobs (the shapes `enqueueMany` takes, without a
     * `unique_key`) and, in $options, the callback jobs `on_complete`, `on_success`, `on_failure` (the same shapes), a
     * `description` and a `context`. `on_failure` is enqueued at the first dead member, `on_complete` once every member
     * completed or was dead-lettered, `on_success` then too when none was dead; each once, with
     * `['batch' => [id, kind, total, succeeded, failed]]` merged into its payload. Answers `['batch_id', 'total',
     * 'jobs']`; 402 pro_required without a Pro licence.
     */
    public function createBatch(array $jobs, array $options = []): array
    {
        $context = (array)($options['context'] ?? []);
        $body = ['description' => $options['description'] ?? null, 'jobs' => []];
        foreach ($jobs as $item) {
            $body['jobs'][] = $this->itemBody($item, $context);
        }
        foreach (['on_complete', 'on_success', 'on_failure'] as $kind) {
            if (isset($options[$kind])) {
                $body[$kind] = $this->itemBody($options[$kind], $context);
            }
        }
        return $this->post('/api/v1/sdk/batches', $body);
    }

    /**
     * A Pro batch's progress with `GET /sdk/batches/:id`: `['batch_id', 'description', 'status', 'total', 'pending',
     * 'succeeded', 'failed', 'created_at', 'finished_at']`; `status` is pending, then success (no member dead) or complete.
     */
    public function getBatch(string $batchId): array
    {
        return $this->get('/api/v1/sdk/batches/' . rawurlencode($batchId));
    }

    /**
     * Enqueues a defined job with its queue, retries and sealed fields (options: delay_ms, jid, unique_key, context).
     * @param class-string<Job> $jobClass
     */
    public function enqueue(string $jobClass, array $payload = [], array $options = []): array
    {
        return $this->enqueueJob($jobClass::$queue, $jobClass::jobName(), $payload, $options + [
            'max_retries' => $jobClass::$retries,
            'encrypt_fields' => $jobClass::$encryptedFields,
            'unique_ttl_ms' => $jobClass::$uniqueTtlMs,
        ]);
    }

    public function enqueueJob(
        string $queue,
        string $jobType,
        array $payload = [],
        array $options = []
    ): array {
        return $this->post('/api/v1/sdk/jobs', $this->jobBody($queue, $jobType, $payload, $options));
    }

    private function jobBody(string $queue, string $jobType, array $payload, array $options): array
    {
        return [
            'queue' => $queue,
            'job_type' => $jobType,
            'payload' => (object)$payload,
            'context' => (object)$this->resolveContext((array)($options['context'] ?? [])),
            'jid' => $options['jid'] ?? null,
            'max_retries' => $options['max_retries'] ?? 3,
            'delay_ms' => $options['delay_ms'] ?? 0,
            'run_at_ms' => $options['run_at_ms'] ?? null,
            'expires_ms' => $options['expires_ms'] ?? null,
            'timeout_ms' => $options['timeout_ms'] ?? null,
            'encrypt_fields' => $options['encrypt_fields'] ?? [],
            'unique_key' => $options['unique_key'] ?? null,
            'unique_mode' => $options['unique_mode'] ?? null,
            'unique_ttl_ms' => $options['unique_ttl_ms'] ?? null,
        ];
    }

    public function startWorkflow(string $name, mixed $input = null, array $options = []): array
    {
        return $this->post('/api/v1/sdk/workflows', [
            'name' => $name,
            'input' => $input,
            'context' => (object)$this->resolveContext((array)($options['context'] ?? [])),
            'id' => $options['id'] ?? null,
            'search_attributes' => $options['search_attributes'] ?? null,
            'build' => $options['build'] ?? null,
        ]);
    }

    /**
     * Registers a recurring job schedule with `POST /sdk/schedules`. Pass exactly one of
     * `cron` or `every` ("<count> <unit>", e.g. "3 seconds") in $options. Answers `['id', 'name', 'kind', 'created']`.
     */
    public function registerSchedule(string $name, string $jobType, string $queue, array $options = []): array
    {
        return $this->post('/api/v1/sdk/schedules', [
            'name' => $name,
            'kind' => 'job',
            'cron' => $options['cron'] ?? null,
            'every' => $options['every'] ?? null,
            'timezone' => $options['timezone'] ?? 'UTC',
            'queue' => $queue,
            'job_type' => $jobType,
            'payload' => (object)($options['payload'] ?? []),
            'max_retries' => $options['max_retries'] ?? 3,
            'encrypt_fields' => $options['encrypt_fields'] ?? [],
            'unique_key' => $options['unique_key'] ?? null,
        ]);
    }

    /** Consumes one token from the `$key` bucket (`$limit` per `$periodMs`). Answers `['allowed', 'retry_after_ms']`. */
    public function rateLimit(string $key, int $limit, int $periodMs): array
    {
        return $this->post('/api/v1/sdk/rate-limit', [
            'key' => $key,
            'limit' => $limit,
            'period_ms' => $periodMs,
        ]);
    }

    /** Sends signal `$name` with `$payload` to the workflow's open run. */
    public function signalWorkflow(string $id, string $name, mixed $payload = null): array
    {
        return $this->post('/api/v1/sdk/workflows/' . rawurlencode($id) . '/signal', [
            'name' => $name,
            'payload' => $payload,
        ]);
    }

    /**
     * Sends an update to a running workflow's update handler `$name` (Pro; 402 without a licence) and waits up to
     * `$waitMs` (100 to 30000, default 10000) for its outcome: `['update_id', 'name', 'status', 'result', 'error',
     * 'reason', 'message']`. `status` is completed, rejected (validate failed: `reason`, `message`), failed, or accepted
     * when the handler had not answered in time (the gateway's 202; send again with the same `$updateId` to wait for the
     * same update).
     */
    public function updateWorkflow(string $id, string $name, mixed $input = null, ?string $updateId = null, ?int $waitMs = null): array
    {
        $body = ['name' => $name, 'input' => $input];
        if ($updateId !== null) {
            $body['update_id'] = $updateId;
        }
        if ($waitMs !== null) {
            $body['wait_ms'] = $waitMs;
        }
        return $this->post('/api/v1/sdk/workflows/' . rawurlencode($id) . '/updates', $body);
    }

    /**
     * One run (Pro; 402 without a licence): `['id', 'name', 'status', 'closed', 'run', 'started_at', 'closed_at',
     * 'continued_to', 'output', 'failure', 'attributes', 'queries']`. Payload fields with secret-looking names are
     * masked, as in the console.
     */
    public function describeWorkflow(string $id): array
    {
        return $this->get('/api/v1/sdk/workflows/' . rawurlencode($id));
    }

    /**
     * The run at the end of the workflow's continue-as-new chain (Pro; 402 without a licence), waiting up to `$waitMs`
     * (at most 25000) for it to close; same shape as `describeWorkflow`. `closed` false means it was still open when
     * the wait ended.
     */
    public function workflowResult(string $id, int $waitMs = 0): array
    {
        return $this->get('/api/v1/sdk/workflows/' . rawurlencode($id) . '/result?wait_ms=' . $waitMs);
    }

    /** The run's events after `$afterSeq` (Pro; 402 without a licence), at most `$limit`, oldest first. */
    public function workflowHistory(string $id, int $afterSeq = 0, int $limit = 200): array
    {
        $res = $this->get('/api/v1/sdk/workflows/' . rawurlencode($id) . "/history?after_seq={$afterSeq}&limit={$limit}");
        return (array)($res['items'] ?? []);
    }

    /** Asks the run the read-only query `$name` (Pro; 402 without a licence); answers its result (any JSON value). */
    public function queryWorkflow(string $id, string $name): mixed
    {
        return $this->post('/api/v1/sdk/workflows/' . rawurlencode($id) . '/query', ['name' => $name])['result'] ?? null;
    }

    /**
     * Sets (`$set`, name => value) and/or removes (`$remove`, names) search attributes of the workflow's open run (Pro;
     * 402 without a licence). Answers `['id', 'attributes']`.
     */
    public function upsertWorkflowAttributes(string $id, ?array $set = null, ?array $remove = null): array
    {
        return $this->post('/api/v1/sdk/workflows/' . rawurlencode($id) . '/search-attributes', [
            'set' => $set === null ? null : (object)$set,
            'remove' => $remove === null ? null : array_values($remove),
        ]);
    }

    /** Sends a workflow's blueprint; the gateway keeps each new content hash (`created`) and ignores a known one. */
    public function registerBlueprint(WorkflowBlueprint $workflow, ?string $workerId = null): array
    {
        return $this->post('/api/v1/sdk/blueprints', [
            'name' => $workflow->name,
            'sdk_language' => 'php',
            'worker_id' => $workerId,
            'blueprint' => $workflow->toBlueprint(),
        ]);
    }

    public function registerWorker(
        string $workerId,
        array $taskQueues,
        int $concurrency = 4,
        ?string $serviceName = null,
        ?string $team = null
    ): array {
        return $this->post('/api/v1/sdk/workers/register', [
            'worker_id' => $workerId,
            'sdk_language' => 'php',
            'sdk_version' => self::SDK_VERSION,
            'service_name' => $serviceName,
            'team' => $team ?? (getenv('JOOBQ_TEAM') ?: null),
            'host' => gethostname() ?: 'php-worker',
            'pid' => getmypid() ?: 1,
            'task_queues' => array_values($taskQueues),
            'concurrency' => $concurrency,
            'delivery_mode' => 'poll',
        ]);
    }

    public function pollTasks(string $workerId, array $taskQueues, int $maxTasks = 1, int $timeoutMs = 0, int $leaseTtlMs = 30000): array
    {
        $res = $this->post('/api/v1/sdk/tasks/poll', [
            'worker_id' => $workerId,
            'task_queues' => array_values($taskQueues),
            'max_tasks' => $maxTasks,
            'timeout_ms' => $timeoutMs,
            'lease_ttl_ms' => $leaseTtlMs,
        ]);
        return $res['tasks'] ?? [];
    }

    public function deregisterWorker(string $workerId): array
    {
        return $this->post('/api/v1/sdk/workers/' . rawurlencode($workerId) . '/deregister', []);
    }

    public function heartbeatTask(string $leaseToken, string $workerId, int $leaseTtlMs = 30000): array
    {
        return $this->post('/api/v1/sdk/tasks/' . rawurlencode($leaseToken) . '/heartbeat', [
            'worker_id' => $workerId,
            'lease_ttl_ms' => $leaseTtlMs,
        ]);
    }

    public function completeTask(string $leaseToken, string $workerId, mixed $output = null): array
    {
        return $this->post('/api/v1/sdk/tasks/' . rawurlencode($leaseToken) . '/complete', [
            'worker_id' => $workerId,
            'output' => $output,
        ]);
    }

    public function failTask(string $leaseToken, string $workerId, \Throwable $error, bool $retryable = true): array
    {
        return $this->post('/api/v1/sdk/tasks/' . rawurlencode($leaseToken) . '/fail',
            ['worker_id' => $workerId] + self::failure($error, $retryable));
    }

    /**
     * Settles up to 100 leases in one call (`POST /sdk/tasks/ack`): items are `['token', 'outcome' => 'complete', 'output']`
     * or `['token', 'outcome' => 'fail'] + JoobQClient::failure($e)`; each gets its own result.
     */
    public function ackTasks(string $workerId, array $items): array
    {
        return $this->post('/api/v1/sdk/tasks/ack', ['worker_id' => $workerId, 'items' => array_values($items)]);
    }

    /** Renews many leases in one call (`POST /sdk/tasks/heartbeat`): `$leases` are `['token']`. */
    public function heartbeatTasks(string $workerId, array $leases, int $leaseTtlMs = 30000): array
    {
        return $this->post('/api/v1/sdk/tasks/heartbeat', ['worker_id' => $workerId, 'lease_ttl_ms' => $leaseTtlMs, 'leases' => array_values($leases)]);
    }

    /** The fields that report `$error` to the gateway (`failTask`, and a `fail` item of `ackTasks`). */
    public static function failure(\Throwable $error, bool $retryable = true): array
    {
        $shouldRetry = $retryable && !($error instanceof NonRetryableException);
        $frames = [];
        foreach ($error->getTrace() as $frame) {
            $frames[] = [
                'file' => $frame['file'] ?? 'unknown',
                'line' => (int)($frame['line'] ?? 0),
                'function' => ($frame['class'] ?? '') . ($frame['type'] ?? '') . ($frame['function'] ?? 'unknown'),
            ];
        }
        $class = get_class($error);
        $message = $error->getMessage() !== '' ? $error->getMessage() : $class;
        $raw = $class . ': ' . $error->getMessage() . "\n" . $error->getTraceAsString();
        return [
            'error_class' => $class,
            'error_message' => mb_substr($message, 0, 4000),
            'retryable' => $shouldRetry,
            'sdk_language' => 'php',
            'stack_frames' => $frames,
            'raw_stacktrace' => mb_substr($raw, 0, 4000),
        ];
    }

    private function resolveContext(array $explicit): array
    {
        $ambient = $this->contextProvider ? (array)($this->contextProvider)() : [];
        return array_merge($ambient, $explicit);
    }

    /**
     * A curl handle for one call (`GatewayCalls` runs several at once); null without ext-curl. A null $body makes it a
     * GET with no body and no Content-Type.
     */
    public function prepare(string $path, ?array $body, ?\CurlHandle $handle = null): ?\CurlHandle
    {
        if (!function_exists('curl_init')) {
            return null;
        }
        $ch = $handle ?? curl_init();
        $method = $body === null
            ? [CURLOPT_HTTPGET => true, CURLOPT_HTTPHEADER => $this->headers(false)]
            : [
                CURLOPT_POST => true,
                CURLOPT_POSTFIELDS => json_encode((object)$body, JSON_THROW_ON_ERROR),
                CURLOPT_HTTPHEADER => [...$this->headers(true), 'Expect:'],
            ];
        curl_setopt_array($ch, [
            CURLOPT_URL => $this->gatewayUrl . $path,
            CURLOPT_RETURNTRANSFER => true,
            CURLOPT_CONNECTTIMEOUT => 10,
            CURLOPT_TIMEOUT_MS => (int)round($this->requestTimeout * 1000),
        ] + $method);
        return $ch;
    }

    /** The fixed headers of every gateway call, for both transports; $json adds the body's Content-Type. */
    private function headers(bool $json): array
    {
        $headers = ["Authorization: Bearer {$this->token}", 'X-JoobQ-SDK: php/' . self::SDK_VERSION];
        return $json ? [...$headers, 'Content-Type: application/json'] : $headers;
    }

    /** The gateway's answer to a curl call: its JSON, or a GatewayException / RuntimeException. */
    public static function answer(\CurlHandle $ch, string|false|null $raw, string $path): array
    {
        if ($raw === false || $raw === null || curl_errno($ch) !== 0) {
            throw new \RuntimeException("JoobQ Gateway request failed: {$path}: " . curl_error($ch));
        }
        $status = (int)curl_getinfo($ch, CURLINFO_RESPONSE_CODE);
        if ($status >= 300) {
            throw GatewayException::of($status, $raw);
        }
        return $raw === '' ? [] : json_decode($raw, true, 512, JSON_THROW_ON_ERROR);
    }

    private function post(string $path, array $body): array
    {
        return $this->send($path, $body);
    }

    private function get(string $path): array
    {
        return $this->send($path, null);
    }

    /** One gateway call: a POST of $body as JSON, or a GET when $body is null. */
    private function send(string $path, ?array $body): array
    {
        if (function_exists('curl_init')) {
            // One kept-alive connection per process: a pool process must not share its parent's.
            if ($this->curl === null || $this->curlPid !== getmypid()) {
                $this->curl = curl_init();
                $this->curlPid = (int)getmypid();
            }
            $ch = $this->prepare($path, $body, $this->curl);
            return self::answer($ch, curl_exec($ch), $path);
        }
        $header = implode("\r\n", $this->headers($body !== null)) . "\r\n";
        $http = $body === null
            ? ['method' => 'GET', 'header' => $header]
            : [
                'method' => 'POST',
                'header' => $header,
                'content' => json_encode((object)$body, JSON_THROW_ON_ERROR),
            ];
        $ctx = stream_context_create(['http' => $http + ['ignore_errors' => true, 'timeout' => $this->requestTimeout]]);
        $raw = @file_get_contents($this->gatewayUrl . $path, false, $ctx);
        if ($raw === false) {
            throw new \RuntimeException("JoobQ Gateway request failed: {$path}");
        }
        $status = 0;
        foreach ($http_response_header ?? [] as $line) {
            if (preg_match('#^HTTP/\S+\s+(\d{3})#', $line, $m)) {
                $status = (int)$m[1];
            }
        }
        if ($status >= 300) {
            throw GatewayException::of($status, $raw);
        }
        return json_decode($raw, true, 512, JSON_THROW_ON_ERROR);
    }
}

/**
 * Several gateway calls at once, for the pool's parent process: `curl_multi` with ext-curl; without it each call is made
 * when it is started (the parent then waits for it, the pool processes still do not).
 */
final class GatewayCalls
{
    private ?\CurlMultiHandle $multi;
    /** @var array<int, array{\CurlHandle, string, \Closure}> */
    private array $running = [];

    public function __construct(private readonly JoobQClient $client)
    {
        $this->multi = function_exists('curl_multi_init') ? curl_multi_init() : null;
    }

    /** Starts a call; `$done(?array $answer, ?\Throwable $error)` runs from `pump` when it ends. */
    public function start(string $path, array $body, \Closure $done): void
    {
        $ch = $this->multi === null ? null : $this->client->prepare($path, $body);
        if ($ch === null) {
            try {
                $answer = (fn () => $this->post($path, $body))->call($this->client);
                $done($answer, null);
            } catch (\Throwable $e) {
                $done(null, $e);
            }
            return;
        }
        curl_multi_add_handle($this->multi, $ch);
        $this->running[spl_object_id($ch)] = [$ch, $path, $done];
    }

    public function active(): bool
    {
        return $this->running !== [];
    }

    /** Moves the running calls on, waiting up to `$wait` seconds for one of them, and finishes the ones that ended. */
    public function pump(float $wait): void
    {
        if ($this->multi === null || $this->running === []) {
            return;
        }
        curl_multi_exec($this->multi, $still);
        if ($wait > 0 && curl_multi_select($this->multi, $wait) > 0) {
            curl_multi_exec($this->multi, $still);
        }
        while ($info = curl_multi_info_read($this->multi)) {
            $ch = $info['handle'];
            [, $path, $done] = $this->running[spl_object_id($ch)];
            unset($this->running[spl_object_id($ch)]);
            curl_multi_remove_handle($this->multi, $ch);
            try {
                $answer = JoobQClient::answer($ch, curl_multi_getcontent($ch), $path);
            } catch (\Throwable $e) {
                $done(null, $e);
                continue;
            }
            $done($answer, null);
        }
    }
}

/**
 * In-app worker. `run()` registers the worker and its workflows' blueprints, then runs tasks.
 *
 * With ext-pcntl and ext-posix it is a parent and a pool of `concurrency` worker processes (even when `concurrency` is
 * 1) that run the tasks, one at a time each. The
 * parent makes every gateway call, so a pool process never waits for HTTP: it long-polls into a small buffer (free
 * processes plus `prefetch`), hands each task to a free process over a pipe, sends the outcomes they hand back in
 * batches (`POST /sdk/tasks/ack`, after at most `ackLingerMs`, retried while the gateway is unavailable; a task stays
 * leased until its outcome is acknowledged; when `ackBuffer` outcomes wait, no new task is handed out), renews every
 * lease in one call (`POST /sdk/tasks/heartbeat`) and re-registers every 10 s, all at once with curl_multi. It replaces a
 * process that died and, on SIGTERM/SIGINT (or `stop()`), stops polling, lets the processes finish what they hold
 * (`drainTimeoutMs`), sends the outcomes and deregisters. Processes share nothing: each is a copy of the booted
 * application made at the fork, so state one task changes is not seen by another, and a connection opened before the
 * fork is shared by every process. Open connections lazily, or in `onProcessStart`, which each pool process calls once
 * before it takes tasks (its return value is ignored), like Resque's `after_fork`. When the hook throws, that process
 * logs `joobq: onProcessStart failed: <message>` and ends (SIGKILL, none of the parent's destructors or shutdown
 * functions run in it) without taking a task; the parent starts the next one after a pause that doubles from 0.25 s to
 * 5 s, and after 5 such processes in a row `run()` deregisters and throws a \RuntimeException. Without ext-pcntl or
 * ext-posix it runs one task at a time in this process, makes its calls itself (said once in the log when
 * `concurrency` > 1) and never calls `onProcessStart`.
 */
final class JoobQWorker
{
    private array $handlers = [];
    private array $middlewares = [];
    private array $taskQueues;
    /** @var array<string, WorkflowBlueprint> */
    private array $workflows = [];
    private array $blueprintsSent = [];
    /** Pool processes in a row that may end before they are ready (see `runPool`) before the worker stops. */
    private const MAX_FAILED_STARTS = 5;
    /** Seconds the pool processes get to end after a refusal before they are killed. */
    private const REAP_TIMEOUT = 5.0;
    private bool $stopping = false;
    private readonly int $prefetch;
    private readonly int $ackBuffer;

    public function __construct(
        private readonly JoobQClient $client,
        private readonly string $workerId,
        array $taskQueues = [],
        private readonly int $leaseTtlMs = 30000,
        private readonly ?string $serviceName = null,
        private readonly int $pollTimeoutMs = 5000,
        private readonly int $concurrency = 1,
        private readonly ?\Closure $onProcessStart = null,
        private readonly int $drainTimeoutMs = 30000,
        ?int $prefetch = null,
        ?int $ackBuffer = null,
        private readonly int $ackLingerMs = 5
    ) {
        $this->taskQueues = array_values($taskQueues);
        $this->prefetch = max(0, $prefetch ?? max(1, intdiv(max(1, $concurrency), 2)));
        $this->ackBuffer = max(1, $ackBuffer ?? 4 * max(1, $concurrency));
        // One hung call must not outlast the leases: a poll waits `pollTimeoutMs` at the gateway, and a sixth of a
        // lease on top keeps a renewal that hangs well inside the lease (10 s with the defaults).
        $bound = $pollTimeoutMs / 1000 + $leaseTtlMs / 6000;
        if ($client->requestTimeout > $bound) {
            $client->requestTimeout = $bound;
        }
    }

    public function use(callable $middleware): self
    {
        $this->middlewares[] = $middleware;
        return $this;
    }

    /** @param class-string<Job> $jobClass */
    public function registerJob(string $jobClass): self
    {
        $queue = $jobClass::$queue;
        if ($queue !== '' && !in_array($queue, $this->taskQueues, true)) {
            $this->taskQueues[] = $queue;
        }
        $this->handlers[$jobClass::jobName()] = fn (mixed $payload, ExecutionContext $ctx) => $jobClass::perform((array)$payload, $ctx);
        return $this;
    }

    public function registerWorkflow(WorkflowBlueprint $workflow): self
    {
        if ($workflow->taskQueue !== '' && !in_array($workflow->taskQueue, $this->taskQueues, true)) {
            $this->taskQueues[] = $workflow->taskQueue;
        }
        $this->workflows[$workflow->name] = $workflow;
        // The engine conducts the workflow's runs and sends each step as its own task.
        $this->handlers = $workflow->activities() + $this->handlers;
        return $this;
    }

    public function handleJob(string $jobType, callable $handler): self
    {
        $this->handlers[$jobType] = $handler;
        return $this;
    }

    /** Runs a task and sends its outcome (`POST /sdk/tasks/ack`). A pool process hands the outcome to its parent instead. */
    public function processTask(array $task): array
    {
        [$status, $item] = $this->runTask($task);
        $this->report(fn () => $this->client->ackTasks($this->workerId, [$item]));
        return $status;
    }

    /** @return array{array, array} the status for the caller and the outcome item for `ackTasks` */
    private function runTask(array $task): array
    {
        $name = (string)($task['name'] ?? '');
        $token = (string)($task['lease_token'] ?? '');
        if (!isset($this->handlers[$name])) {
            $item = ['token' => $token, 'outcome' => 'fail'] + JoobQClient::failure(new NonRetryableException("No handler registered for {$name} [JQ-901] https://joobq.io/errors/JQ-901"), false);
            return [['status' => 'failed'], $item];
        }
        $ctx = new ExecutionContext($task, $this->workerId, $this->client, $this->leaseTtlMs);
        $handler = $this->handlers[$name];
        $runner = fn () => $handler($task['payload'] ?? null, $ctx);
        foreach (array_reverse($this->middlewares) as $mw) {
            $next = $runner;
            $runner = fn () => $mw($ctx, $next);
        }
        try {
            $output = $runner();
        } catch (\Throwable $e) {
            return [['status' => 'failed'], ['token' => $token, 'outcome' => 'fail'] + JoobQClient::failure($e)];
        }
        return [['status' => 'completed', 'output' => $output], ['token' => $token, 'outcome' => 'complete', 'output' => $output]];
    }

    /**
     * Sends an outcome, retrying while the gateway is unavailable; a lost outcome is left to the lease. Throws an
     * SdkTooOldException (not retried).
     */
    private function report(callable $call): void
    {
        $delay = 250;
        for ($i = 0; $i < 6; $i++) {
            try {
                $call();
                return;
            } catch (SdkTooOldException $e) {
                throw $e; // every call is refused: never retried
            } catch (GatewayException $e) {
                if ($e->status < 500) {
                    return;
                }
            } catch (\Throwable) {
            }
            usleep($delay * 1000);
            $delay = min($delay * 2, 5000);
        }
    }

    /** Stops polling; `run()` returns once the running tasks have finished and their outcomes are acknowledged. */
    public function stop(): void
    {
        $this->stopping = true;
    }

    /** Whether this process can fork a pool: ext-pcntl and ext-posix (a pool process ends itself with SIGKILL). */
    private function pooled(): bool
    {
        return function_exists('pcntl_fork') && function_exists('pcntl_waitpid') && function_exists('posix_kill')
            && function_exists('stream_socket_pair');
    }

    private function register(): void
    {
        $this->registerBlueprints(); // first: a worker that shows up has its blueprints in
        $this->client->registerWorker($this->workerId, $this->taskQueues, $this->pooled() ? $this->concurrency : 1, serviceName: $this->serviceName);
    }

    /** Registers every workflow's blueprint once; one the gateway refuses (4xx) is logged and not sent again. */
    private function registerBlueprints(): void
    {
        foreach ($this->workflows as $name => $workflow) {
            if (isset($this->blueprintsSent[$name])) {
                continue;
            }
            try {
                $this->client->registerBlueprint($workflow, $this->workerId);
            } catch (GatewayException $e) {
                if ($e->status >= 500 || $e instanceof SdkTooOldException) {
                    throw $e;
                }
                error_log("joobq: blueprint of {$name} refused: {$e->getMessage()} [JQ-902] https://joobq.io/errors/JQ-902");
            }
            $this->blueprintsSent[$name] = true;
        }
    }

    /**
     * Runs until SIGTERM/SIGINT or `stop()`, then deregisters. Throws a \RuntimeException (after deregistering) when
     * the pool cannot keep its processes up: 5 in a row ended before they could take a task (onProcessStart threw).
     * Throws an SdkTooOldException at once when the gateway refuses this SDK's version (426 on any of its calls): it
     * logs the server's message, stops polling and sending, and neither drains nor deregisters (the gateway would
     * refuse those calls too; the leases expire and the tasks are queued again). A task a pool process is running
     * gets up to 5 s to end (its outcome cannot be sent), then the process is killed; every process is reaped.
     */
    public function run(): void
    {
        if (function_exists('pcntl_async_signals')) {
            pcntl_async_signals(true);
            pcntl_signal(SIGTERM, fn () => $this->stop());
            pcntl_signal(SIGINT, fn () => $this->stop());
        }
        $backoff = 250;
        while (!$this->stopping) {
            try {
                $this->register();
                break;
            } catch (SdkTooOldException $e) {
                error_log($e->logLine());
                throw $e;
            } catch (\Throwable) {
                usleep($backoff * 1000);
                $backoff = min($backoff * 2, 5000);
            }
        }
        try {
            if ($this->pooled()) {
                $this->runPool();
            } else {
                if ($this->concurrency > 1) {
                    error_log('joobq: ext-pcntl or ext-posix is not loaded; the worker runs one task at a time');
                }
                $this->pollLoop();
            }
        } catch (SdkTooOldException $e) {
            $refused = true; // not deregistered: the gateway refuses that call too
            error_log($e->logLine());
            throw $e;
        } finally {
            if (!isset($refused)) {
                try {
                    $this->client->deregisterWorker($this->workerId);
                } catch (\Throwable) {
                }
            }
        }
    }

    /** One JSON line down a pipe (blocking: the other end reads whole lines). */
    private static function send(mixed $pipe, array $message): bool
    {
        $line = json_encode($message, JSON_THROW_ON_ERROR | JSON_PRESERVE_ZERO_FRACTION) . "\n";
        while ($line !== '') {
            $written = @fwrite($pipe, $line);
            if ($written === false) {
                return false;
            }
            if ($written === 0) {
                $r = null;
                $w = [$pipe];
                $e = null;
                if (@stream_select($r, $w, $e, 1) === false) {
                    return false;
                }
                continue;
            }
            $line = substr($line, $written);
        }
        return true;
    }

    /** Forks a pool process with a pipe to it; null when the fork failed. */
    private function spawnChild(): ?array
    {
        $pair = stream_socket_pair(STREAM_PF_UNIX, STREAM_SOCK_STREAM, STREAM_IPPROTO_IP);
        if ($pair === false) {
            return null;
        }
        $pid = pcntl_fork();
        if ($pid === 0) {
            fclose($pair[0]);
            $this->runChild($pair[1]);
        }
        fclose($pair[1]);
        if ($pid < 0) {
            fclose($pair[0]);
            return null;
        }
        stream_set_blocking($pair[0], false);
        return ['pid' => $pid, 'pipe' => $pair[0], 'buffer' => '', 'task' => null, 'ready' => false];
    }

    /**
     * A pool process: calls `onProcessStart`, says it is ready, then reads a task, runs it and hands the outcome back,
     * until its pipe closes. It never returns into the parent's code: it ends itself with SIGKILL, also when the hook
     * throws (logged), so the parent's destructors and shutdown functions never run in it.
     */
    private function runChild(mixed $pipe): never
    {
        pcntl_signal(SIGTERM, SIG_IGN); // the parent drains: it closes the pipe once the work is done
        pcntl_signal(SIGINT, SIG_IGN);
        try {
            if ($this->onProcessStart !== null) {
                try {
                    ($this->onProcessStart)();
                } catch (\Throwable $e) {
                    error_log("joobq: onProcessStart failed: {$e->getMessage()}");
                    posix_kill(getmypid(), SIGKILL);
                }
            }
            if (!self::send($pipe, ['ready' => true])) {
                posix_kill(getmypid(), SIGKILL);
            }
            while (($line = fgets($pipe)) !== false) {
                $message = json_decode($line, true);
                if (!is_array($message) || !isset($message['task'])) {
                    continue;
                }
                [, $item] = $this->runTask($message['task']);
                if (!self::send($pipe, ['outcome' => $item])) {
                    break;
                }
            }
        } finally {
            posix_kill(getmypid(), SIGKILL); // gone without the parent's destructors
        }
        exit(0);
    }

    /** The pool's parent: the event loop that runs the transport (see the class comment). */
    private function runPool(): void
    {
        $calls = new GatewayCalls($this->client);
        $children = [];
        $ready = [];       // leased tasks waiting for a free process
        $leased = [];      // every lease held: token => true
        $acks = [];        // outcomes waiting to be sent
        $ackSince = null;  // when the oldest waiting outcome arrived
        $polling = $acking = $beating = false;
        $ackRetryAt = 0.0;
        $ackMax = 100; // halved while the gateway answers 413 (a batch too large for one call)
        $ackDelay = 0.25;
        $pollRetryAt = 0.0;
        $pollDelay = 0.25;
        $every = max(0.5, $this->leaseTtlMs / 3000);
        $nextBeat = microtime(true) + $every;
        $lastRegister = microtime(true);
        $capacity = $this->concurrency + $this->prefetch;
        $deadline = null;
        // Respawn guard: a process that ends before it says it is ready (onProcessStart threw, or it crashed) is
        // replaced after a pause that doubles from 0.25 s to 5 s, one at a time; MAX_FAILED_STARTS in a row stop the worker.
        $failedStarts = 0;
        $everReady = false;
        $spawnDelay = 0.25;
        $spawnAt = 0.0;
        $fatal = null;
        // The gateway refused this SDK's version (426) on one of its calls: the loop ends at once, without a drain.
        $refused = null;

        $release = function (string $token) use (&$leased): void {
            unset($leased[$token]);
        };
        $reap = function (int $pid) use (&$children, &$failedStarts, &$everReady, &$spawnDelay, &$spawnAt, $release): void {
            $child = $children[$pid];
            unset($children[$pid]); // replaced on a later turn
            if ($child['task'] !== null) {
                $release((string)$child['task']['lease_token']); // what it held is left to its lease
            }
            if (!$child['ready']) { // it may have said so just before it died
                $child['ready'] = str_contains($child['buffer'] . @stream_get_contents($child['pipe']), '"ready":true');
            }
            fclose($child['pipe']);
            if ($child['ready']) {
                $everReady = true;
                $failedStarts = 0;
                $spawnDelay = 0.25;
                return;
            }
            if ($this->stopping) {
                return;
            }
            $failedStarts++;
            $spawnAt = microtime(true) + $spawnDelay;
            $spawnDelay = min($spawnDelay * 2, 5.0);
        };

        while ($refused === null) {
            $now = microtime(true);
            if ($this->stopping && $deadline === null) {
                $deadline = $now + $this->drainTimeoutMs / 1000;
            }
            if (!$this->stopping && $failedStarts >= self::MAX_FAILED_STARTS) {
                $fatal = "{$failedStarts} pool processes in a row ended before they could take a task"
                    . ' (did onProcessStart fail? see the log); the worker stops';
                error_log("joobq: {$fatal}");
                $this->stopping = true;
                $deadline = $now + $this->drainTimeoutMs / 1000;
            }
            if ($fatal !== null && $ready !== []) { // also what a poll still running brings in
                foreach ($ready as $task) {
                    $release((string)$task['lease_token']); // not run here: left to its lease
                }
                $ready = [];
            }
            if (!$this->stopping && $now >= $spawnAt) {
                while (count($children) < $this->concurrency) {
                    // Until a process has started cleanly (and after one did not), start them one at a time.
                    $starting = count(array_filter($children, fn ($c) => !$c['ready']));
                    if (($failedStarts > 0 || !$everReady) && $starting > 0) {
                        break;
                    }
                    $child = $this->spawnChild();
                    if ($child === null) {
                        break;
                    }
                    $children[$child['pid']] = $child;
                }
            }
            $busy = count(array_filter($children, fn ($c) => $c['task'] !== null));

            // Hand buffered tasks to free processes, unless the outcome queue is full (back-pressure).
            foreach ($children as $pid => $child) {
                if ($ready === [] || count($acks) >= $this->ackBuffer) {
                    break;
                }
                if ($child['task'] !== null || !$child['ready']) {
                    continue;
                }
                $task = array_shift($ready);
                if (!self::send($child['pipe'], ['task' => $task])) {
                    array_unshift($ready, $task);
                    continue;
                }
                $children[$pid]['task'] = $task;
                $busy++;
            }

            // Poll for more while there is room.
            $held = $busy + count($ready);
            if (!$this->stopping && !$polling && $held < $capacity && $now >= $pollRetryAt) {
                $polling = true;
                $calls->start('/api/v1/sdk/tasks/poll', [
                    'worker_id' => $this->workerId, 'task_queues' => array_values($this->taskQueues),
                    'max_tasks' => min($capacity - $held, 100), 'timeout_ms' => $this->pollTimeoutMs, 'lease_ttl_ms' => $this->leaseTtlMs,
                ], function (?array $answer, ?\Throwable $error) use (&$polling, &$ready, &$leased, &$pollRetryAt, &$pollDelay, &$refused): void {
                    $polling = false;
                    if ($error instanceof SdkTooOldException) {
                        $refused ??= $error;
                        return;
                    }
                    if ($error !== null) {
                        $pollRetryAt = microtime(true) + $pollDelay + random_int(0, 100) / 1000;
                        $pollDelay = min($pollDelay * 2, 5.0);
                        return;
                    }
                    $pollDelay = 0.25;
                    foreach ($answer['tasks'] ?? [] as $task) {
                        $leased[(string)$task['lease_token']] = true;
                        $ready[] = $task;
                    }
                });
            }

            // Send the outcomes: 100 at once, or what waited `ackLingerMs`, or everything when stopping.
            if (!$acking && $acks !== [] && $now >= $ackRetryAt
                && (count($acks) >= $ackMax || $this->stopping || $now - $ackSince >= $this->ackLingerMs / 1000)) {
                $batch = array_splice($acks, 0, $ackMax);
                $ackSince = $acks === [] ? null : $now;
                $acking = true;
                $calls->start('/api/v1/sdk/tasks/ack', ['worker_id' => $this->workerId, 'items' => $batch],
                    function (?array $answer, ?\Throwable $error) use (&$acking, &$acks, &$ackSince, &$ackRetryAt, &$ackDelay, &$ackMax, $batch, $release, &$deadline, &$refused): void {
                        $acking = false;
                        if ($error instanceof SdkTooOldException) {
                            $refused ??= $error; // never retried: the outcomes are left to their leases
                            return;
                        }
                        if ($error instanceof GatewayException && $error->status === 413 && count($batch) > 1) {
                            array_unshift($acks, ...$batch); // too large for one call: smaller batches
                            $ackSince ??= microtime(true);
                            $ackMax = max(1, intdiv(count($batch), 2));
                            return;
                        }
                        if ($error === null) {
                            $ackMax = 100;
                        }
                        $retry = $error !== null && !($error instanceof GatewayException && $error->status < 500 && $error->status !== 429);
                        if ($retry && ($deadline === null || microtime(true) < $deadline)) {
                            array_unshift($acks, ...$batch); // still leased: renewed until it is acknowledged
                            $ackSince ??= microtime(true);
                            $ackRetryAt = microtime(true) + $ackDelay;
                            $ackDelay = min($ackDelay * 2, 5.0);
                            return;
                        }
                        if ($error !== null && !$retry) {
                            error_log('joobq: the gateway refused ' . count($batch) . " outcomes: {$error->getMessage()}");
                        }
                        $ackDelay = 0.25;
                        foreach ($batch as $item) {
                            $release((string)$item['token']);
                        }
                    });
            }

            // Renew every lease every third of its time.
            if (!$beating && $leased !== [] && $now >= $nextBeat) {
                $nextBeat = $now + $every;
                $leases = array_map(fn ($token) => ['token' => $token], array_slice(array_keys($leased), 0, 500));
                $beating = true;
                $calls->start('/api/v1/sdk/tasks/heartbeat', ['worker_id' => $this->workerId, 'lease_ttl_ms' => $this->leaseTtlMs, 'leases' => $leases],
                    function (?array $answer, ?\Throwable $error) use (&$beating, &$leased, &$refused): void {
                        $beating = false;
                        if ($error instanceof SdkTooOldException) {
                            $refused ??= $error;
                            return;
                        }
                        if ($error !== null) {
                            return; // renewed with the next heartbeat
                        }
                        foreach ($answer['leases'] ?? [] as $lease) {
                            if (!empty($lease['error'])) {
                                unset($leased[(string)$lease['lease_token']]); // gone: its outcome will be refused
                            }
                        }
                    });
            }
            if (!$this->stopping && $now - $lastRegister > 10) {
                $lastRegister = $now;
                $calls->start('/api/v1/sdk/workers/register', [
                    'worker_id' => $this->workerId, 'sdk_language' => 'php', 'sdk_version' => JoobQClient::SDK_VERSION,
                    'service_name' => $this->serviceName, 'team' => getenv('JOOBQ_TEAM') ?: null, 'host' => gethostname() ?: 'php-worker',
                    'pid' => getmypid() ?: 1, 'task_queues' => array_values($this->taskQueues), 'concurrency' => $this->concurrency,
                    'delivery_mode' => 'poll',
                ], function (?array $answer, ?\Throwable $error) use (&$refused): void {
                    if ($error instanceof SdkTooOldException) {
                        $refused ??= $error;
                    }
                });
            }

            // Done: stopping, nothing held or the drain time is up, and the outcomes sent (or given up on).
            if ($this->stopping) {
                $drained = $busy === 0 && $ready === [];
                $late = microtime(true) >= $deadline;
                if (($drained || $late) && (($acks === [] && !$acking && !$polling) || microtime(true) >= $deadline + 5)) {
                    break;
                }
            }

            // Wait for a pool process or a gateway call, briefly.
            $pipes = array_map(fn ($c) => $c['pipe'], $children);
            $working = $busy > 0 || $acks !== [] || $ready !== [];
            $wait = $working ? 0.001 : 0.01; // the long poll is nearly always running: look at it often
            if ($pipes !== []) {
                $r = array_values($pipes);
                $w = null;
                $e = null;
                if (@stream_select($r, $w, $e, 0, (int)($wait * 1_000_000)) > 0) {
                    foreach ($r as $pipe) {
                        foreach ($children as $pid => $child) {
                            if ($child['pipe'] !== $pipe) {
                                continue;
                            }
                            $chunk = fread($pipe, 65536);
                            if ($chunk === '' || $chunk === false) {
                                if (feof($pipe)) { // died
                                    $reap($pid);
                                    pcntl_waitpid($pid, $status, WNOHANG);
                                }
                                break;
                            }
                            $children[$pid]['buffer'] .= $chunk;
                            while (($nl = strpos($children[$pid]['buffer'], "\n")) !== false) {
                                $line = substr($children[$pid]['buffer'], 0, $nl);
                                $children[$pid]['buffer'] = substr($children[$pid]['buffer'], $nl + 1);
                                $message = json_decode($line, true);
                                if (!empty($message['ready'])) {
                                    $children[$pid]['ready'] = $everReady = true;
                                    $failedStarts = 0;
                                    $spawnDelay = 0.25;
                                }
                                if (isset($message['outcome'])) {
                                    $acks[] = $message['outcome'];
                                    $ackSince ??= microtime(true);
                                    $children[$pid]['task'] = null;
                                }
                            }
                            break;
                        }
                    }
                }
                $calls->pump(0);
            } else {
                $calls->pump($wait);
            }
            while (($pid = pcntl_waitpid(-1, $status, WNOHANG)) > 0) {
                if (isset($children[$pid])) {
                    $reap($pid);
                }
            }
        }
        foreach ($children as $pid => $child) {
            fclose($child['pipe']); // it reads end of file and exits
            if ($refused === null) {
                posix_kill($pid, SIGKILL); // one still running a task gives it up: left to its lease
                pcntl_waitpid($pid, $status);
            }
        }
        if ($refused !== null) {
            $this->reapRefused(array_keys($children));
            throw $refused;
        }
        if ($fatal !== null) {
            throw new \RuntimeException("joobq: {$fatal}");
        }
    }

    /**
     * After a refusal: waits up to REAP_TIMEOUT seconds for the pool processes (their pipes are closed, so an idle one
     * ends at once and a busy one when its task is done), then kills and reaps the rest, so none is left a zombie or
     * an orphan. A handler still running at that deadline is cut short (its outcome could not be sent anyway: the
     * task is left to its lease).
     *
     * @param list<int> $pids
     */
    private function reapRefused(array $pids): void
    {
        $deadline = microtime(true) + self::REAP_TIMEOUT;
        while ($pids !== [] && microtime(true) < $deadline) {
            foreach ($pids as $i => $pid) {
                if (pcntl_waitpid($pid, $status, WNOHANG) !== 0) { // ended (or not ours any more)
                    unset($pids[$i]);
                }
            }
            if ($pids !== []) {
                usleep(20_000);
            }
        }
        foreach ($pids as $pid) {
            posix_kill($pid, SIGKILL);
            pcntl_waitpid($pid, $status);
        }
    }

    /** Without ext-pcntl: one task at a time, the calls made here. */
    private function pollLoop(): void
    {
        $lastRegister = microtime(true);
        $backoff = 250;
        while (!$this->stopping) {
            try {
                if (microtime(true) - $lastRegister > 10) {
                    $this->register();
                    $lastRegister = microtime(true);
                }
                $tasks = $this->client->pollTasks($this->workerId, $this->taskQueues, 1, $this->pollTimeoutMs, $this->leaseTtlMs);
                $backoff = 250;
            } catch (SdkTooOldException $e) {
                throw $e; // never retried: `run()` stops
            } catch (\Throwable) {
                usleep(($backoff + random_int(0, 100)) * 1000);
                $backoff = min($backoff * 2, 5000);
                continue;
            }
            foreach ($tasks as $task) {
                $this->processTask($task);
            }
        }
    }

    /** @deprecated use run() */
    public function start(): void
    {
        $this->run();
    }
}
